class Solution { public:int minOperations(vector<int>& nums){int ones=count(nums.begin(),nums.end(),1);if(ones)return nums.size()-ones;int best=INT_MAX;for(int left=0;left<(int)nums.size();++left){int value=0;for(int right=left;right<(int)nums.size();++right){value=gcd(value,nums[right]);if(value==1){best=min(best,right-left+1);break;}}}return best==INT_MAX?-1:best+nums.size()-2;} };
